 public static function paymentExportAllowed(array$source,string$admission):bool{return$admission==='allow';}public static function historicalExportAllowed(array$source):bool{return true;}
 public static function build(array$source):array
 {
  $num=static fn($value,int$scale=1)=>$value===null?'':(int)$value/$scale;$mode=(string)($source['mode']??'draft');if(!in_array($mode,['draft','history','payment'],true))throw new \InvalidArgumentException('EXPORT_MODE_INVALID');$calculation=$source['calculation'];if($mode==='payment'&&($calculation['status']??null)!=='accepted')throw new \DomainException('PAYMENT_EXPORT_STATE_INVALID');$label=$mode==='draft'?'Черновик. Не основание выплаты':($mode==='history'?'Историческая выгрузка':'Реестр к выплате');
  $sheets=['Расчёт ОТиЗ'=>[['Режим',$label],['Расчёт',(int)$calculation['id']],['Дата',$calculation['reportDate']],['Сумма, руб.',(int)$calculation['totalCents']/100]],'Объекты'=>[['Регномер','Адрес','Фонд, руб.','Начислено, руб.','Сроки, руб.','Дисциплина, руб.','К выплате, руб.']],'Работники'=>[['Регномер','Табельный номер','ФИО','Вес','Доля, б.п.','Сумма, руб.']],'Контроль'=>[['Код','Сообщение']],'Приложение к приказу'=>[['Табельный номер','ФИО','Сумма, руб.']],'Метаданные'=>[['Поле','Значение'],['Версия правил',$calculation['rulesVersion']??'otiz-v2'],['Revision',(int)$calculation['revision']]],'Удержания'=>[['Объект','Работник','Сумма, руб.','Причина','Документ']],'Решения по выплате'=>[['Работник','Решение','Причина']]];
  $reg=[];foreach($source['objects']??[]as$o){$reg[(string)$o['objectId']]=$o['regnumber'];$sheets['Объекты'][]=[$o['regnumber'],$o['address']??'',$num($o['fundCents']??null,100),$num($o['grossCents']??null,100),$num($o['deadlineCents']??null,100),$num($o['disciplineCents']??null,100),$num($o['payableCents']??null,100)];}
