 }
 private static function sheet(array$rows):string{$x='<?xml version="1.0" encoding="UTF-8"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><printTitles>1:1</printTitles><sheetData>';$r=1;$max=1;foreach($rows as$row){$x.='<row r="'.$r++.'">';$max=max($max,count($row));foreach($row as$v)$x.=is_int($v)||is_float($v)?'<c t="n"><v>'.$v.'</v></c>':'<c t="inlineStr"><is><t>'.self::xml($v).'</t></is></c>';$x.='</row>';}$last=chr(64+min(26,$max));return$x.'</sheetData><autoFilter ref="A1:'.$last.'1"/><pageSetup orientation="landscape" fitToWidth="1"/></worksheet>';}
 private static function xml(mixed$v):string{return htmlspecialchars((string)$v,ENT_XML1|ENT_QUOTES,'UTF-8');}private static function types(int$n):string{$x='<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>';for($i=1;$i<=$n;$i++)$x.='<Override PartName="/xl/worksheets/sheet'.$i.'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>';return$x.'</Types>';}
 private static function zip(array$files):string{$body='';$central='';$offset=0;foreach($files as$name=>$data){$crc=(int)sprintf('%u',crc32($data));$l=strlen($data);$nl=strlen($name);$local=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,0,$crc,$l,$l,$nl,0).$name.$data;$body.=$local;$central.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,0,$crc,$l,$l,$nl,0,0,0,0,0,$offset).$name;$offset+=strlen($local);}return$body.$central.pack('VvvvvVVv',0x06054b50,0,0,count($files),count($files),strlen($central),strlen($body),0);}
